const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const deathValley = ee.FeatureCollection('USGS/GAP/NLCD/2006')
      .filter(ee.Filter.eq('AREA_NAME', 'Death Valley National Park'))
      .geometry();

    const date1_start = '2022-07-11';
    const date1_end = '2022-07-12'; // To get an image for July 11
    const date2_start = '2022-08-07';
    const date2_end = '2022-08-08'; // To get an image for August 7

    const scale = 1000; // Use a coarser scale for area calculation to avoid memory issues

    // Function to mask clouds in Sentinel-2 imagery
    function maskS2clouds(image) {
      const qa = image.select('SCL');
      // Clouds (8, 9, 10), Cloud Shadows (3), Snow/Ice (11), Saturated (1)
      const cloudMask = qa.eq(8).or(qa.eq(9)).or(qa.eq(10)).or(qa.eq(3)).or(qa.eq(11)).or(qa.eq(1)).not();
      // Mask out bad pixels and return the image
      return image.updateMask(cloudMask).copyProperties(image, ['system:time_start']);
    }

    // Function to calculate MNDWI and create a water mask
    function calculateMNDWI(image) {
      // MNDWI = (Green - SWIR1) / (Green + SWIR1)
      // Sentinel-2 bands: B3 (Green), B11 (SWIR1)
      const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
      // Threshold MNDWI to identify water. A common threshold is > 0.
      const waterMask = mndwi.gt(0.1).rename('water_mask'); // Using 0.1 for a slightly stricter threshold
      return image.addBands(mndwi).addBands(waterMask);
    }

    // Function to get and process image for a specific date range
    async function getImageAndWaterArea(dateStart, dateEnd, geometry, name) {
      let collection = ee.ImageCollection('COPERNICUS/S2_SR')
        .filterBounds(geometry)
        .filterDate(dateStart, dateEnd)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)); // Pre-filter by cloud percentage

      const colSize = await collection.size().getInfo();
      if (colSize === 0) {
        console.log(`${name} Images: 0`);
        return { waterArea: null, pixelCount: 0, imageCount: 0 };
      }

      // Sort by cloudiness and take the least cloudy image
      const image = collection.sort('CLOUDY_PIXEL_PERCENTAGE').first();
      const maskedImage = maskS2clouds(image);

      // Check for valid pixels after masking
      const initialPixelCount = await maskedImage.select('B3').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('B3').getInfo();

      if (initialPixelCount === 0) {
        console.log(`${name} Images: ${colSize} (Val: 0.0, Cloudy: ${image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo().toFixed(1)}%)`);
        return { waterArea: null, pixelCount: 0, imageCount: colSize };
      }

      const processedImage = calculateMNDWI(maskedImage);

      // Calculate water area
      const waterImage = processedImage.select('water_mask').selfMask(); // Mask out non-water pixels
      const waterPixelCount = await waterImage.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
      }).get('water_mask').getInfo();

      if (waterPixelCount === 0) {
        console.log(`${name} Images: ${colSize} (Val: 0.0, Cloudy: ${image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo().toFixed(1)}%)`);
        return { waterArea: 0, pixelCount: 0, imageCount: colSize }; // Valid zero water area
      }

      // Area of one pixel at the given scale in square meters
      const pixelAreaSqM = ee.Number(scale).pow(2);
      const waterAreaSqKm = ee.Number(waterPixelCount).multiply(pixelAreaSqM).divide(1e6).getInfo();

      console.log(`${name} Images: ${colSize} (Cloudy: ${image.get('CLOUDY_PIXEL_PERCENTAGE').getInfo().toFixed(1)}%, Pixels: ${waterPixelCount})`);
      return { waterArea: waterAreaSqKm, pixelCount: waterPixelCount, imageCount: colSize };
    }

    // 2. Data Acquisition & Check
    const result_july = await getImageAndWaterArea(date1_start, date1_end, deathValley, 'July 11, 2022');
    const result_august = await getImageAndWaterArea(date2_start, date2_end, deathValley, 'Aug 7, 2022');

    if (result_july.imageCount === 0 || result_august.imageCount === 0) {
      console.log("No images found for one or both comparison points.");
      console.log("C1");
      return;
    }
    if (result_july.pixelCount === 0 || result_august.pixelCount === 0) {
      console.log("No valid pixels after cloud masking or water detection for one or both comparison points.");
      console.log("C2");
      return;
    }

    const waterArea_july = result_july.waterArea;
    const waterArea_august = result_august.waterArea;

    // 5. Validation & Final Answer
    if (waterArea_july === null || waterArea_august === null) {
      console.log("Calculation resulted in null/None.");
      console.log("C3");
      return;
    }

    console.log(`Surface water area on July 11, 2022: ${waterArea_july.toFixed(2)} sq km`);
    console.log(`Surface water area on August 7, 2022: ${waterArea_august.toFixed(2)} sq km`);

    if (waterArea_august > waterArea_july) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.error("Analysis failed:", error);
    console.log("D"); // Catch other errors like band name incorrect, memory issues etc.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
